print(f"Output size: {len(output_grid)}x{len(output_grid[0])}")

# Identify unique colors
all_colors = set()
for row in input_grid + output_grid:
    for cell in row:
        all_colors.add(cell)
all_colors.discard(6)  # 6 is background
print(f"Non-background colors: {sorted(all_colors)}")

# Look at the transformation pattern
# Find non-background cells and see what changed
print("\n=== Transform analysis ===")
for r in range(min(5, len(input_grid))):
    in_row = input_grid[r]
